核心逻辑可整理为：
void MyWeatherPrediction::showResult() const {
    cout << format(
        "Tomorrow's temperature will be {} degrees Celsius {} degrees Fahrenheit",
        getTomorrowTempCelsius(),
        getTomorrowTempFahrenheit());
    cout << format("Chance of rain is {}%", getChanceOfRain() * 100) << endl;
    if (getChanceOfRain() > 0.5) {
        cout << "Bring an umbrella!";
    }
}
